'use client';

import { useEffect, useRef } from 'react';
import { createGarden, type CreateGardenOptions } from '../scenes/garden';
import '../engine/scene.css';

export type GardenController = ReturnType<typeof createGarden>;
type GardenProps = CreateGardenOptions & {
  className?: string;
  fallback?: string;
  onReady?: (garden: GardenController | null) => void;
  onError?: (error: Error) => void;
};

/** Keep callbacks stable. Changes to the scene options remount only this instance. */
export function GardenCanvas({ className = '', fallback, onReady, onError, onFrame, initialTime = 16, timeScale = 1, seed = 1486, cycleSeconds = 120, wind = 1, plants, paused = false }: GardenProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    let garden: GardenController;
    try {
      garden = createGarden(canvas, { initialTime, timeScale, seed, cycleSeconds, wind, plants, paused, onFrame });
    } catch (error) {
      onError?.(error instanceof Error ? error : new Error(String(error)));
      return;
    }
    onReady?.(garden);
    return () => { garden.destroy(); onReady?.(null); };
  }, [initialTime, timeScale, seed, cycleSeconds, wind, plants, paused, onReady, onError, onFrame]);

  return <div className={`interactive-art-scene ${className}`}>
    {fallback && <img className="interactive-art-fallback" src={fallback} alt="" aria-hidden="true" />}
    <canvas ref={canvasRef} role="img" aria-label="A lotus garden with growing buds and a repeating day and night cycle. Each flower has a button for keyboard interaction." />
  </div>;
}

import { colour, mix, randomSource, smooth, TAU, type Point, type RGB } from '../engine/math';
import { boundedTarget, chainSnapshot, createChain, simulateChain, updateRest, type ElasticChain } from '../engine/elastic';
import { mountScene, type PaintState, type RuntimeOptions, type SceneDefinition, type SceneInput } from '../engine/runtime';

export const GARDEN_SIZE = { width: 1000, height: 680 };
export const GARDEN_LAYERS = ['sky', 'celestial', 'landscape', 'water', 'pads', 'stems', 'leaves', 'blossoms', 'foreground', 'grain'] as const;
export type GardenLayer = typeof GARDEN_LAYERS[number];
type Shade = 'ivory' | 'violet' | 'rose';
type Palette = readonly [RGB, RGB, RGB, RGB];
const LEAF_JOINTS: readonly (readonly [number, number])[] = [[3, -1], [5, 1]];

export type PlantDefinition = {
  x: number;
  height: number;
  radius: number;
  lean: number;
  delay: number;
  duration: number;
  shade: Shade;
};

type Plant = PlantDefinition & {
  id: string;
  rootY: number;
  growth: number;
  bloom: number;
  chain: ElasticChain;
};

export const DEFAULT_PLANTS: readonly PlantDefinition[] = [
  { x: 115, height: 235, radius: 34, lean: -.24, delay: -30, duration: 75, shade: 'violet' },
  { x: 278, height: 290, radius: 49, lean: -.16, delay: -38, duration: 72, shade: 'ivory' },
  { x: 438, height: 207, radius: 38, lean: -.08, delay: 0, duration: 72, shade: 'rose' },
  { x: 578, height: 370, radius: 63, lean: .12, delay: -44, duration: 78, shade: 'ivory' },
  { x: 744, height: 250, radius: 43, lean: .15, delay: -12, duration: 68, shade: 'violet' },
  { x: 902, height: 285, radius: 39, lean: .2, delay: 12, duration: 85, shade: 'rose' },
];

function restPoints(definition: PlantDefinition, rootY: number, growth: number): Point[] {
  const height = definition.height * mix(.26, 1, growth);
  return Array.from({ length: 9 }, (_, index) => {
    const progress = index / 8;
    return { x: definition.x + Math.sin(progress * 1.35) * height * definition.lean, y: rootY - height * progress };
  });
}

function createPlant(definition: PlantDefinition, index: number): Plant {
  if (![definition.x, definition.height, definition.radius, definition.lean, definition.delay, definition.duration].every(Number.isFinite) || definition.height <= 0 || definition.radius <= 0 || definition.duration <= 0) {
    throw new Error('Plant dimensions and growth duration must be positive finite numbers.');
  }
  const rootY = 594 + (index % 2) * 18;
  return { ...definition, id: `flower-${index + 1}`, rootY, growth: 0, bloom: 0,
    chain: createChain(restPoints(definition, rootY, 0), definition.height * .34) };
}

function tipOf(plant: Plant) {
  const tip = plant.chain.nodes.at(-1);
  if (!tip) throw new Error('Missing flower tip.');
  return tip;
}

export function gardenLighting(elapsed: number, cycleSeconds = 120) {
  const phase = (elapsed % cycleSeconds) / cycleSeconds;
  const daylight = smooth((Math.sin(phase * TAU) + .32) / .9);
  return { phase, daylight, name: daylight < .14 ? 'Night' : daylight < .64 ? 'Twilight' : 'Day' };
}

function petalPath(context: CanvasRenderingContext2D, width: number, height: number, bend = 0) {
  context.beginPath();
  context.moveTo(0, 7);
  context.bezierCurveTo(-width, -height * .2, -width * .92 + bend, -height * .74, bend, -height);
  context.bezierCurveTo(width * .94 + bend, -height * .68, width, -height * .18, 0, 7);
  context.closePath();
}

function drawLeaf(context: CanvasRenderingContext2D, x: number, y: number, size: number, rotation: number, daylight: number) {
  context.save(); context.translate(x, y); context.rotate(rotation);
  petalPath(context, size * .27, size, size * .12);
  const gradient = context.createLinearGradient(-size * .2, 0, size * .3, -size);
  gradient.addColorStop(0, colour([23, 58, 65], [36, 90, 69], daylight));
  gradient.addColorStop(1, colour([44, 91, 97], [100, 144, 108], daylight));
  context.fillStyle = gradient; context.fill();
  context.strokeStyle = '#1f3443'; context.lineWidth = 1.5; context.stroke();
  context.strokeStyle = colour([109, 148, 127], [176, 189, 121], daylight, .8);
  context.lineWidth = .7;
  context.beginPath(); context.moveTo(0, 4); context.quadraticCurveTo(size * .03, -size * .5, size * .12, -size * .96); context.stroke();
  for (let index = 1; index < 7; index++) {
    const p = index / 8;
    const width = Math.sin(p * Math.PI) * size * .19;
    context.beginPath(); context.moveTo(size * p * .08, -size * p);
    context.quadraticCurveTo(-width * .7, -size * (p + .04), -width, -size * (p + .12));
    context.moveTo(size * p * .08, -size * p);
    context.quadraticCurveTo(width * .7, -size * (p + .04), width + size * .06, -size * (p + .12)); context.stroke();
  }
  context.restore();
}

function drawPetal(context: CanvasRenderingContext2D, rotation: number, width: number, height: number, palette: Palette, daylight: number, texture: CanvasPattern, bend = 0) {
  context.save(); context.rotate(rotation);
  petalPath(context, width, height, bend);
  const gradient = context.createLinearGradient(-width, 5, width * .6, -height);
  gradient.addColorStop(0, colour(palette[0], palette[1], daylight));
  gradient.addColorStop(.64, colour(palette[1], palette[2], daylight));
  gradient.addColorStop(1, colour(palette[2], palette[3], daylight));
  context.fillStyle = gradient; context.fill();
  context.save(); context.clip(); context.globalAlpha = .095; context.fillStyle = texture;
  context.fillRect(-width * 2, -height - 4, width * 4, height + 16); context.restore();
  context.strokeStyle = colour([25, 37, 65], [47, 56, 71], daylight); context.lineWidth = 1.45; context.stroke();
  context.strokeStyle = colour([114, 118, 119], [186, 165, 116], daylight, .78); context.lineWidth = .65;
  context.beginPath(); context.moveTo(0, 4); context.quadraticCurveTo(bend * .4, -height * .43, bend, -height * .94); context.stroke();
  for (let index = 1; index < 5; index++) {
    const p = index / 6, w = Math.sin(p * Math.PI) * width * .66;
    context.beginPath(); context.moveTo(bend * p * .4, -height * p);
    context.quadraticCurveTo(-w * .5, -height * (p + .06), -w + bend * p, -height * (p + .17));
    context.moveTo(bend * p * .4, -height * p);
    context.quadraticCurveTo(w * .5, -height * (p + .06), w + bend * p, -height * (p + .17)); context.stroke();
  }
  context.restore();
}

const PALETTES: Record<Shade, Palette> = {
  ivory: [[145, 157, 157], [211, 216, 204], [243, 236, 212], [255, 248, 224]],
  violet: [[77, 71, 112], [120, 102, 150], [169, 156, 191], [213, 207, 220]],
  rose: [[101, 66, 98], [164, 108, 137], [219, 170, 185], [246, 216, 212]],
};

function drawFlower(context: CanvasRenderingContext2D, plant: Plant, daylight: number, texture: CanvasPattern, selected: boolean) {
  const tip = tipOf(plant);
  const radius = plant.radius * mix(.53, 1, plant.growth);
  const bloom = plant.bloom;
  context.save(); context.translate(tip.x, tip.y); context.rotate(plant.chain.headAngle * .85);
  if (selected) {
    context.save(); context.globalAlpha = .35; context.strokeStyle = '#e6d39c'; context.lineWidth = 1;
    context.setLineDash([2, 6]); context.beginPath(); context.ellipse(0, -radius * .35, radius * 1.4, radius * 1.1, 0, 0, TAU); context.stroke(); context.restore();
  }
  const unfolding = smooth((bloom - .04) / .16);
  if (unfolding < 1) {
    context.save(); context.globalAlpha *= 1 - unfolding;
    drawPetal(context, -.1, radius * .32, radius * 1.05, PALETTES[plant.shade], daylight, texture, radius * .03);
    drawPetal(context, .13, radius * .21, radius * 1.06, PALETTES[plant.shade], daylight, texture, -radius * .04);
    drawLeaf(context, -2, 8, radius * .57, -.34, daylight);
    drawLeaf(context, 2, 8, radius * .52, .4, daylight);
    context.restore();
  }
  if (unfolding > 0) {
    context.save(); context.globalAlpha *= unfolding;
    const open = smooth((bloom - .04) / .96);
    for (let index = -4; index <= 4; index++) {
      drawPetal(context, index * .34 * mix(.3, 1, open), radius * mix(.17, .33, open), radius * (1.38 - Math.abs(index) * .048), PALETTES[plant.shade], daylight, texture, index * 1.1);
    }
    for (let index = -3; index <= 3; index++) {
      drawPetal(context, index * .45 * mix(.2, 1, open), radius * mix(.17, .34, open), radius * (.98 - Math.abs(index) * .035), PALETTES[plant.shade], daylight, texture, -index * .7);
    }
    context.save(); context.scale(1, .54);
    context.fillStyle = colour([163, 137, 68], [226, 192, 95], daylight); context.strokeStyle = '#8c7548'; context.lineWidth = 1;
    context.beginPath(); context.ellipse(0, -radius * .07, radius * .3 * open, radius * .25 * open, 0, 0, TAU); context.fill(); context.stroke();
    for (let index = 0; index < 31; index++) {
      const a = index * 2.399, r = Math.sqrt(index / 31) * radius * .28 * open;
      context.fillStyle = index % 3 ? '#dfc988' : '#776344';
      context.beginPath(); context.arc(Math.cos(a) * r, -radius * .07 + Math.sin(a) * r, .9, 0, TAU); context.fill();
    }
    context.restore();
    for (let index = -2; index <= 2; index++) {
      drawPetal(context, index * .76 * open + Math.PI * .17 * Math.sign(index), radius * .29, radius * (.6 - Math.abs(index) * .035), PALETTES[plant.shade], daylight, texture, index);
    }
    context.restore();
  }
  context.restore();
}

function drawStem(context: CanvasRenderingContext2D, plant: Plant, daylight: number) {
  const nodes = plant.chain.nodes;
  const root = nodes[0];
  if (!root) return;
  context.beginPath(); context.moveTo(root.x, root.y);
  for (let index = 1; index < nodes.length - 1; index++) {
    const node = nodes[index], next = nodes[index + 1];
    if (!node || !next) continue;
    context.quadraticCurveTo(node.x, node.y, (node.x + next.x) / 2, (node.y + next.y) / 2);
  }
  const tip = tipOf(plant);
  context.lineTo(tip.x, tip.y);
  context.lineCap = 'round'; context.strokeStyle = '#243b47'; context.lineWidth = 7; context.stroke();
  context.strokeStyle = colour([89, 116, 89], [177, 175, 113], daylight); context.lineWidth = 3.4; context.stroke();
}

function drawLeaves(context: CanvasRenderingContext2D, plant: Plant, daylight: number) {
  const nodes = plant.chain.nodes;
  for (const [index, side] of LEAF_JOINTS) {
    const node = nodes[index], previous = nodes[index - 1];
    if (!node || !previous) continue;
    const angle = Math.atan2(node.y - previous.y, node.x - previous.x) + Math.PI / 2;
    const growth = smooth((plant.growth - .12 * index) / .44);
    drawLeaf(context, node.x, node.y, plant.radius * 1.4 * growth, angle + side * .98, daylight);
  }
}

function drawLilyPad(context: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, daylight: number) {
  context.save(); context.translate(x, y); context.rotate(rotation); context.scale(1, .48);
  context.beginPath(); context.moveTo(0, 0); context.arc(0, 0, radius, -.28, TAU - .53); context.closePath();
  const gradient = context.createRadialGradient(-radius * .3, -radius * .3, 0, 0, 0, radius);
  gradient.addColorStop(0, colour([51, 95, 105], [126, 155, 108], daylight));
  gradient.addColorStop(1, colour([24, 52, 70], [55, 98, 88], daylight));
  context.fillStyle = gradient; context.fill(); context.strokeStyle = '#20384e'; context.lineWidth = 2; context.stroke();
  context.strokeStyle = colour([110, 147, 128], [174, 183, 127], daylight, .6); context.lineWidth = .8;
  for (let index = 1; index < 16; index++) {
    const a = index / 16 * TAU;
    context.beginPath(); context.moveTo(0, 0); context.quadraticCurveTo(Math.cos(a - .12) * radius * .48, Math.sin(a + .12) * radius * .48, Math.cos(a) * radius * .98, Math.sin(a) * radius * .98); context.stroke();
  }
  context.restore();
}

export type GardenOptions = {
  seed?: number;
  cycleSeconds?: number;
  wind?: number;
  plants?: readonly PlantDefinition[];
};

/** Garden-specific art, growth, and input response. Scheduling belongs to the runtime. */
export function createGardenScene(options: GardenOptions = {}) {
  const seed = options.seed ?? 1486, cycleSeconds = options.cycleSeconds ?? 120, wind = options.wind ?? 1;
  if (!Number.isInteger(seed) || seed < 0 || seed > 4294967295) throw new Error('Seed must be an unsigned 32-bit integer.');
  if (!Number.isFinite(cycleSeconds) || cycleSeconds <= 0) throw new Error('Cycle length must be positive and finite.');
  if (!Number.isFinite(wind) || wind < 0) throw new Error('Wind must be finite and nonnegative.');
  const random = randomSource(seed);
  const plants = (options.plants ?? DEFAULT_PLANTS).map(createPlant);
  const orderedPlants = [...plants].sort((a, b) => a.rootY - b.rootY);
  const grass = Array.from({ length: 190 }, () => ({ x: random() * GARDEN_SIZE.width, y: 578 + random() * 108, height: 22 + random() * 75, lean: random() * 2 - 1, phase: random() * TAU }));
  const stars = Array.from({ length: 55 }, () => ({ x: 35 + random() * 930, y: 30 + random() * 250, radius: .45 + random() * 1.1 }));
  const pads = Array.from({ length: 13 }, () => ({ x: random() * GARDEN_SIZE.width, y: 454 + random() * 200, radius: 35 + random() * 72, rotation: random() * .6 - .3 }));
  const textureCanvas = document.createElement('canvas');
  textureCanvas.width = textureCanvas.height = 96;
  const textureContext = textureCanvas.getContext('2d');
  if (!textureContext) throw new Error('Canvas 2D is unavailable.');
  const pixels = textureContext.createImageData(96, 96);
  for (let index = 0; index < pixels.data.length; index += 4) {
    const shade = Math.floor(random() * 255);
    pixels.data[index] = pixels.data[index + 1] = pixels.data[index + 2] = shade;
    pixels.data[index + 3] = 130;
  }
  textureContext.putImageData(pixels, 0, 0);
  const texture = textureContext.createPattern(textureCanvas, 'repeat');
  if (!texture) throw new Error('Could not create the garden texture.');
  let impulse: { id: string; target: Point; until: number } | null = null;

  function inspect() {
    return { seed, plants: plants.map(plant => ({ id: plant.id, growth: plant.growth, bloom: plant.bloom, ...chainSnapshot(plant.chain) })) };
  }

  return {
    size: GARDEN_SIZE,
    layers: GARDEN_LAYERS,
    update(elapsed: number, resetPose: boolean) {
      for (const plant of plants) {
        plant.growth = smooth((elapsed - plant.delay) / plant.duration);
        plant.bloom = smooth((plant.growth - .48) / .52);
        updateRest(plant.chain, restPoints(plant, plant.rootY, plant.growth), resetPose);
      }
    },
    step(dt: number, physicalTime: number, input: SceneInput) {
      for (const plant of plants) {
        let target: Point | null = null;
        if (input.drag?.id === plant.id) {
          target = { x: input.drag.target.x, y: input.drag.target.y + plant.radius * .4 };
        } else if (impulse?.id === plant.id && physicalTime < impulse.until) {
          target = impulse.target;
        } else if (input.pointer) {
          const tip = tipOf(plant), distance = Math.hypot(input.pointer.x - tip.x, input.pointer.y - tip.y);
          if (distance < plant.radius * 2) {
            const rest = plant.chain.rest.at(-1);
            if (rest) {
              const influence = smooth(1 - distance / (plant.radius * 2));
              target = { x: rest.x + (input.pointer.x > tip.x ? -1 : 1) * 27 * influence, y: rest.y + 4 * influence };
            }
          }
        }
        simulateChain(plant.chain, dt, physicalTime, wind, target);
      }
    },
    targets() {
      return plants.map((plant, index) => {
        const tip = tipOf(plant);
        return { id: plant.id, label: `Bend lotus ${index + 1}`, x: tip.x, y: tip.y - plant.radius * .4, radius: plant.radius * 1.45 };
      });
    },
    activate(id: string, direction: number, physicalTime: number) {
      const plant = plants.find(item => item.id === id);
      if (!plant) return;
      const rest = plant.chain.rest.at(-1);
      if (rest) impulse = { id, target: boundedTarget(plant.chain, { x: rest.x + Math.sign(direction) * 65, y: rest.y + 12 }), until: physicalTime + .7 };
    },
    release() { impulse = null; },
    inspect,
    paint(context: CanvasRenderingContext2D, state: PaintState, layers: ReadonlySet<GardenLayer>) {
      context.lineCap = 'round';
      const { phase, daylight } = gardenLighting(state.elapsed, cycleSeconds);
      if (layers.has('sky')) {
        const sky = context.createLinearGradient(0, 0, 0, GARDEN_SIZE.height);
        sky.addColorStop(0, colour([12, 25, 54], [89, 147, 171], daylight));
        sky.addColorStop(.65, colour([23, 46, 74], [173, 191, 174], daylight));
        sky.addColorStop(1, colour([24, 57, 66], [99, 147, 126], daylight));
        context.fillStyle = sky;
        context.fillRect(0, 0, GARDEN_SIZE.width, GARDEN_SIZE.height);
      }
      if (layers.has('celestial')) {
        context.save(); context.globalAlpha = 1 - daylight; context.fillStyle = '#dbd6b7';
        for (const star of stars) { context.beginPath(); context.arc(star.x, star.y, star.radius, 0, TAU); context.fill(); }
        context.restore();
        const orbs: readonly (readonly [boolean, number])[] = [[true, phase * TAU], [false, phase * TAU + Math.PI]];
        for (const [isSun, angle] of orbs) {
          const orbX = 500 - Math.cos(angle) * 350, orbY = 415 - Math.sin(angle) * 330;
          const glow = context.createRadialGradient(orbX, orbY, 8, orbX, orbY, 108);
          glow.addColorStop(0, isSun ? 'rgba(255,228,167,.23)' : 'rgba(204,224,233,.12)');
          glow.addColorStop(1, 'rgba(255,228,167,0)');
          context.fillStyle = glow; context.fillRect(orbX - 108, orbY - 108, 216, 216);
          context.fillStyle = isSun ? '#f5dda1' : '#d8dfdb'; context.beginPath(); context.arc(orbX, orbY, isSun ? 25 : 18, 0, TAU); context.fill();
          context.strokeStyle = 'rgba(220,205,149,.3)'; context.lineWidth = .7;
          for (let ring = 0; ring < 3; ring++) { context.beginPath(); context.arc(orbX, orbY, 31 + ring * 7, 0, TAU); context.stroke(); }
        }
      }
      if (layers.has('landscape')) {
        for (let index = 0; index < 3; index++) {
          context.beginPath(); context.moveTo(-50, 380 + index * 45);
          context.bezierCurveTo(160, 330 + index * 48, 208, 405 + index * 28, 480, 357 + index * 40);
          context.bezierCurveTo(692, 316 + index * 36, 830, 394 + index * 29, 1060, 328 + index * 36);
          context.lineTo(1060, 680); context.lineTo(-50, 680); context.closePath();
          context.fillStyle = colour([20 + index * 4, 47 + index * 5, 68 + index * 2], [75 - index * 11, 123 - index * 7, 113 - index * 8], daylight); context.fill();
          context.strokeStyle = colour([88, 116, 118], [170, 181, 129], daylight, .4); context.lineWidth = .8; context.stroke();
        }
      }
      if (layers.has('water')) {
        for (let index = 0; index < 22; index++) {
          const y = 437 + index * 8.5, x = ((index * 163) % 980) - 90;
          context.strokeStyle = colour([82, 131, 137], [170, 188, 150], daylight, .17); context.lineWidth = .9;
          context.beginPath(); context.moveTo(x, y); context.bezierCurveTo(x + 55, y - 7, x + 105, y + 7, x + 185, y); context.stroke();
        }
      }
      if (layers.has('pads')) for (const pad of pads) drawLilyPad(context, pad.x, pad.y, pad.radius, pad.rotation, daylight);
      if (layers.has('stems')) for (const plant of orderedPlants) drawStem(context, plant, daylight);
      if (layers.has('leaves')) for (const plant of orderedPlants) drawLeaves(context, plant, daylight);
      if (layers.has('blossoms')) for (const plant of orderedPlants) drawFlower(context, plant, daylight, texture, state.selectedId === plant.id);
      if (layers.has('foreground')) {
        for (const blade of grass) {
          const sway = state.reducedMotion ? 0 : Math.sin(state.physicalTime * 1.4 + blade.phase) * 7 * wind;
          context.beginPath(); context.moveTo(blade.x, blade.y);
          context.bezierCurveTo(blade.x + blade.lean * 10, blade.y - blade.height * .34, blade.x + blade.lean * 17 + sway, blade.y - blade.height * .85, blade.x + blade.lean * 25 + sway, blade.y - blade.height);
          context.strokeStyle = colour([52, 91, 82], [114, 150, 95], daylight, .82); context.lineWidth = 1.3; context.stroke();
          if (blade.height > 70) {
            context.strokeStyle = colour([138, 147, 111], [211, 195, 129], daylight, .72); context.lineWidth = 2.6;
            context.beginPath(); context.moveTo(blade.x + blade.lean * 25 + sway, blade.y - blade.height);
            context.lineTo(blade.x + blade.lean * 24 + sway, blade.y - blade.height + 8); context.stroke();
          }
        }
      }
      if (layers.has('grain')) {
        context.save(); context.globalAlpha = .045; context.fillStyle = texture;
        context.fillRect(0, 0, GARDEN_SIZE.width, GARDEN_SIZE.height); context.restore();
      }
    },
  } satisfies SceneDefinition<ReturnType<typeof inspect>, GardenLayer>;
}

export type CreateGardenOptions = GardenOptions & RuntimeOptions;

export function createGarden(canvas: HTMLCanvasElement, options: CreateGardenOptions = {}) {
  const scene = createGardenScene(options);
  const runtime = mountScene(canvas, scene, { ...options, initialTime: options.initialTime ?? 16 });
  return {
    ...runtime,
    saveState() { return { version: 1, seed: scene.inspect().seed, elapsed: runtime.snapshot().elapsed }; },
  };
}

/** Parse host-provided saved progress before recreating a garden. Storage stays with the host. */
export function readGardenState(value: unknown) {
  if (typeof value === 'object' && value !== null && 'version' in value && value.version === 1 && 'seed' in value && typeof value.seed === 'number' && Number.isInteger(value.seed) && value.seed >= 0 && value.seed <= 4294967295 && 'elapsed' in value && typeof value.elapsed === 'number' && Number.isFinite(value.elapsed) && value.elapsed >= 0) {
    return { seed: value.seed, initialTime: value.elapsed };
  }
  throw new Error('Saved garden state is invalid.');
}

import { type Point, type Size } from './math';

export type HitRegion = Point & { id: string; label: string; radius: number };
export type SceneInput = { pointer: Point | null; drag: { id: string; target: Point } | null };
export type PaintState = { elapsed: number; physicalTime: number; reducedMotion: boolean; selectedId: string | null };
export type FrameState = PaintState & { paused: boolean; inView: boolean; running: boolean };

export type SceneDefinition<Details, Layer extends string> = {
  size: Size;
  layers: readonly Layer[];
  update: (elapsed: number, resetPose: boolean) => void;
  step: (dt: number, physicalTime: number, input: SceneInput) => void;
  paint: (context: CanvasRenderingContext2D, state: PaintState, layers: ReadonlySet<Layer>) => void;
  targets: () => HitRegion[];
  activate: (id: string, direction: number, physicalTime: number) => void;
  release: () => void;
  inspect: () => Details;
};

export type RuntimeOptions = {
  initialTime?: number;
  timeScale?: number;
  paused?: boolean;
  onFrame?: (state: FrameState) => void;
};

export type ExportOptions<Layer extends string> = {
  layers?: readonly Layer[];
  width?: number;
  height?: number;
};

const STEP = 1 / 120;
const MAX_STEPS = 6;

function nonnegative(value: number, label: string) {
  if (!Number.isFinite(value) || value < 0) throw new Error(`${label} must be a finite nonnegative number.`);
  return value;
}

/** Mount one scene. The host owns its surrounding layout and any persistence. */
export function mountScene<Details, Layer extends string>(canvas: HTMLCanvasElement, scene: SceneDefinition<Details, Layer>, options: RuntimeOptions = {}) {
  const maybeContext = canvas.getContext('2d');
  const host = canvas.parentElement;
  if (!maybeContext || !host) throw new Error('Mount the canvas in a positioned container with Canvas 2D support.');
  const context = maybeContext;
  let elapsed = nonnegative(options.initialTime ?? 0, 'Initial time');
  let timeScale = nonnegative(options.timeScale ?? 1, 'Time scale');
  const motionQuery = matchMedia('(prefers-reduced-motion: reduce)');
  const events = new AbortController();
  const signal = events.signal;
  const allLayers = new Set(scene.layers);
  const originalCursor = canvas.style.cursor;
  const overlay = canvas.ownerDocument.createElement('div');
  overlay.className = 'interactive-art-targets';
  Object.assign(overlay.style, { position: 'absolute', inset: '0', pointerEvents: 'none' });
  host.append(overlay);
  const buttons = new Map<string, HTMLButtonElement>();
  const directions = new Map<string, number>();
  let paused = options.paused ?? false, destroyed = false, inView = false;
  let physicalTime = 0, frame = 0, last: number | null = null, accumulator = 0, renderedFrames = 0;
  let width = 1, height = 1, scale = 1, offsetX = 0, offsetY = 0;
  let pointer: Point | null = null;
  let drag: { id: string; pointerId: number; target: Point; offset: Point; capture: HTMLElement } | null = null;

  const active = () => !destroyed && !paused && inView && !document.hidden && !motionQuery.matches;
  const paintState = (): PaintState => ({ elapsed, physicalTime, reducedMotion: motionQuery.matches, selectedId: drag?.id ?? null });

  function updateTargets() {
    const seen = new Set<string>();
    for (const target of scene.targets()) {
      seen.add(target.id);
      let button = buttons.get(target.id);
      if (!button) {
        button = canvas.ownerDocument.createElement('button');
        button.type = 'button';
        button.className = 'interactive-art-target';
        button.dataset.sceneObject = target.id;
        Object.assign(button.style, { position: 'absolute', pointerEvents: 'auto', touchAction: 'none', borderRadius: '50%', padding: '0', transform: 'translate(-50%, -50%)', background: 'transparent' });
        button.addEventListener('click', event => {
          if (event.detail !== 0 || !active()) return;
          const direction = directions.get(target.id) ?? 1;
          scene.activate(target.id, direction, physicalTime);
          directions.set(target.id, -direction);
        }, { signal });
        overlay.append(button);
        buttons.set(target.id, button);
      }
      const diameter = Math.max(44, target.radius * 2 * scale);
      const x = target.x * scale + offsetX, y = target.y * scale + offsetY;
      const visible = x + diameter / 2 > 0 && x - diameter / 2 < width && y + diameter / 2 > 0 && y - diameter / 2 < height;
      button.hidden = !visible && drag?.id !== target.id;
      button.setAttribute('aria-label', target.label);
      button.disabled = !active() || button.hidden;
      button.style.left = `${x}px`;
      button.style.top = `${y}px`;
      button.style.width = button.style.height = `${diameter}px`;
    }
    for (const [id, button] of buttons) {
      if (!seen.has(id)) { button.remove(); buttons.delete(id); }
    }
  }

  function render() {
    if (destroyed) return;
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.clearRect(0, 0, canvas.width, canvas.height);
    context.setTransform(canvas.width / width * scale, 0, 0, canvas.height / height * scale, canvas.width / width * offsetX, canvas.height / height * offsetY);
    scene.paint(context, paintState(), allLayers);
    renderedFrames++;
    updateTargets();
    options.onFrame?.({ ...paintState(), paused, inView, running: active() });
  }

  function resize() {
    const rect = canvas.getBoundingClientRect();
    width = Math.max(1, rect.width);
    height = Math.max(1, rect.height);
    const density = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(width * density);
    canvas.height = Math.round(height * density);
    scale = height / scene.size.height;
    offsetX = (width - scene.size.width * scale) / 2;
    offsetY = 0;
    render();
  }

  function localPoint(event: PointerEvent): Point {
    const rect = canvas.getBoundingClientRect();
    return { x: (event.clientX - rect.left - offsetX) / scale, y: (event.clientY - rect.top - offsetY) / scale };
  }

  function nearest(point: Point) {
    let closest: HitRegion | null = null, distance = Infinity;
    for (const target of scene.targets()) {
      const d = Math.hypot(point.x - target.x, point.y - target.y);
      if (d < Math.max(target.radius, 22 / scale) && d < distance) { closest = target; distance = d; }
    }
    return closest;
  }

  function clearInteraction() {
    const held = drag;
    drag = null;
    pointer = null;
    scene.release();
    if (held?.capture.hasPointerCapture(held.pointerId)) held.capture.releasePointerCapture(held.pointerId);
    canvas.style.cursor = originalCursor;
  }

  function tick(now: number) {
    frame = 0;
    if (!active()) return;
    const delta = last === null ? 0 : Math.min(MAX_STEPS * STEP, Math.max(0, (now - last) / 1000));
    last = now;
    accumulator += delta;
    let steps = 0;
    while (accumulator >= STEP && steps < MAX_STEPS) {
      elapsed += STEP * timeScale;
      physicalTime += STEP;
      scene.update(elapsed, false);
      scene.step(STEP, physicalTime, { pointer, drag: drag ? { id: drag.id, target: drag.target } : null });
      accumulator -= STEP;
      steps++;
    }
    render();
    if (active()) frame = requestAnimationFrame(tick);
  }

  function schedule() {
    cancelAnimationFrame(frame);
    frame = 0;
    last = null;
    accumulator = 0;
    if (active()) frame = requestAnimationFrame(tick);
  }

  host.addEventListener('pointermove', event => {
    if (!active()) return;
    const point = localPoint(event);
    if (drag?.pointerId === event.pointerId) {
      drag.target = { x: point.x - drag.offset.x, y: point.y - drag.offset.y };
      event.preventDefault();
    } else if (event.pointerType !== 'touch') {
      pointer = point;
      canvas.style.cursor = nearest(point) ? 'grab' : originalCursor;
    }
  }, { signal });
  host.addEventListener('pointerleave', () => { pointer = null; if (!drag) canvas.style.cursor = originalCursor; }, { signal });
  host.addEventListener('pointerdown', event => {
    if (event.button !== 0 || drag || !active()) return;
    const point = localPoint(event), target = nearest(point);
    if (!target) return;
    // Capture only flower targets on touch, leaving the canvas available for page scrolling.
    if (event.pointerType === 'touch' && !(event.target instanceof HTMLButtonElement)) return;
    const capture = event.target instanceof HTMLElement ? event.target : canvas;
    drag = { id: target.id, pointerId: event.pointerId, target: { x: target.x, y: target.y }, offset: { x: point.x - target.x, y: point.y - target.y }, capture };
    pointer = null;
    capture.setPointerCapture(event.pointerId);
    event.preventDefault();
  }, { signal });
  const release = (event: PointerEvent) => { if (drag?.pointerId === event.pointerId) clearInteraction(); };
  host.addEventListener('pointerup', release, { signal });
  host.addEventListener('pointercancel', release, { signal });
  host.addEventListener('lostpointercapture', release, { signal });
  document.addEventListener('visibilitychange', () => { if (document.hidden) clearInteraction(); schedule(); render(); }, { signal });
  motionQuery.addEventListener('change', () => {
    clearInteraction();
    if (motionQuery.matches) scene.update(elapsed, true);
    schedule();
    render();
  }, { signal });
  const sizeObserver = new ResizeObserver(resize);
  sizeObserver.observe(canvas);
  const visibilityObserver = new IntersectionObserver(entries => {
    const entry = entries[0];
    inView = Boolean(entry && entry.isIntersecting && entry.intersectionRatio >= .05);
    if (!inView) clearInteraction();
    schedule();
    render();
  }, { threshold: [0, .05] });
  visibilityObserver.observe(canvas);
  scene.update(elapsed, true);
  resize();

  return {
    pause() { if (destroyed) return; paused = true; clearInteraction(); schedule(); render(); },
    resume() { if (destroyed) return; paused = false; schedule(); render(); },
    setTimeScale(value: number) { if (destroyed) return; timeScale = nonnegative(value, 'Time scale'); },
    seek(seconds: number) {
      if (destroyed) return;
      elapsed = nonnegative(seconds, 'Time');
      clearInteraction();
      scene.update(elapsed, true);
      last = null;
      accumulator = 0;
      render();
    },
    bend(id: string, direction = 1) { if (active()) scene.activate(id, direction, physicalTime); },
    snapshot() {
      return { elapsed, physicalTime, timeScale, paused, inView, hidden: document.hidden, reducedMotion: motionQuery.matches, running: Boolean(frame), destroyed, renderedFrames, drag: drag?.id ?? null,
        view: { width, height, scale, offsetX, offsetY },
        targets: scene.targets().map(target => ({ ...target, screen: { x: target.x * scale + offsetX, y: target.y * scale + offsetY } })),
        details: scene.inspect() };
    },
    async exportPNG(settings: ExportOptions<Layer> = {}) {
      if (destroyed) throw new Error('Cannot export a destroyed scene.');
      const output = canvas.ownerDocument.createElement('canvas');
      const outputWidth = settings.width ?? scene.size.width, outputHeight = settings.height ?? scene.size.height;
      if (![outputWidth, outputHeight].every(value => Number.isInteger(value) && value > 0 && value <= 8192)) throw new Error('Export dimensions must be integers between 1 and 8192.');
      const selected = new Set(settings.layers ?? scene.layers);
      for (const layer of selected) if (!allLayers.has(layer)) throw new Error(`Unknown scene layer: ${layer}`);
      output.width = outputWidth;
      output.height = outputHeight;
      const outputContext = output.getContext('2d');
      if (!outputContext) throw new Error('Canvas 2D is unavailable.');
      const layerCanvas = canvas.ownerDocument.createElement('canvas');
      layerCanvas.width = outputWidth;
      layerCanvas.height = outputHeight;
      const layerContext = layerCanvas.getContext('2d');
      if (!layerContext) throw new Error('Canvas 2D is unavailable.');
      const state = { ...paintState(), selectedId: null };
      // Quantize every layer before composition, just as separate PNG assets are quantized.
      for (const layer of scene.layers) {
        if (!selected.has(layer)) continue;
        layerContext.clearRect(0, 0, outputWidth, outputHeight);
        layerContext.save();
        layerContext.scale(outputWidth / scene.size.width, outputHeight / scene.size.height);
        scene.paint(layerContext, state, new Set([layer]));
        layerContext.restore();
        outputContext.drawImage(layerCanvas, 0, 0);
      }
      return new Promise<Blob>((resolve, reject) => output.toBlob(blob => blob ? resolve(blob) : reject(new Error('PNG export failed.')), 'image/png'));
    },
    destroy() {
      if (destroyed) return;
      destroyed = true;
      cancelAnimationFrame(frame);
      frame = 0;
      clearInteraction();
      events.abort();
      sizeObserver.disconnect();
      visibilityObserver.disconnect();
      overlay.remove();
      buttons.clear();
    },
  };
}

import { mix, type Point } from './math';

type Node = Point & { previousX: number; previousY: number };

export type ElasticChain = {
  nodes: Node[];
  rest: Point[];
  lengths: number[];
  maxPull: number;
  headAngle: number;
  headVelocity: number;
};

/** A fixed root and at least two joints define an anchored elastic object. */
export function createChain(rest: Point[], maxPull: number): ElasticChain {
  if (rest.length < 2 || !Number.isFinite(maxPull) || maxPull <= 0) {
    throw new Error('An elastic chain needs two or more points and a positive pull limit.');
  }
  const chain = {
    nodes: rest.map(point => ({ ...point, previousX: point.x, previousY: point.y })),
    rest,
    lengths: rest.slice(1).map((point, index) => {
      const previous = rest[index];
      if (!previous) throw new Error('Missing chain point.');
      return Math.hypot(point.x - previous.x, point.y - previous.y);
    }),
    maxPull,
    headAngle: 0,
    headVelocity: 0,
  };
  resetChain(chain);
  return chain;
}

export function resetChain(chain: ElasticChain) {
  for (let index = 0; index < chain.nodes.length; index++) {
    const node = chain.nodes[index], rest = chain.rest[index];
    if (!node || !rest) continue;
    node.x = node.previousX = rest.x;
    node.y = node.previousY = rest.y;
  }
  const a = chain.nodes.at(-2), b = chain.nodes.at(-1);
  if (a && b) chain.headAngle = Math.atan2(b.y - a.y, b.x - a.x) + Math.PI / 2;
  chain.headVelocity = 0;
}

/** Growth changes the rest geometry, independently of the simulation clock. */
export function updateRest(chain: ElasticChain, rest: Point[], reset = false) {
  if (rest.length !== chain.nodes.length) throw new Error('The chain joint count must stay constant.');
  chain.rest = rest;
  for (let index = 1; index < rest.length; index++) {
    const a = rest[index - 1], b = rest[index];
    if (a && b) chain.lengths[index - 1] = Math.hypot(b.x - a.x, b.y - a.y);
  }
  if (reset) resetChain(chain);
}

export function boundedTarget(chain: ElasticChain, point: Point): Point {
  const rest = chain.rest.at(-1);
  if (!rest) throw new Error('Missing chain tip.');
  const dx = point.x - rest.x, dy = point.y - rest.y;
  const distance = Math.hypot(dx, dy);
  const ratio = distance > chain.maxPull ? chain.maxPull / distance : 1;
  return { x: rest.x + dx * ratio, y: rest.y + dy * ratio };
}

/** Fixed-step Verlet integration, length constraints, and a separately damped head. */
export function simulateChain(chain: ElasticChain, dt: number, time: number, wind: number, target: Point | null) {
  const root = chain.nodes[0], anchor = chain.rest[0], tipRest = chain.rest.at(-1);
  if (!root || !anchor || !tipRest) return;
  const goal = target ? boundedTarget(chain, target) : null;
  const damping = Math.exp(-(goal ? 11 : 5.8) * dt);
  root.x = root.previousX = anchor.x;
  root.y = root.previousY = anchor.y;
  for (let index = 1; index < chain.nodes.length; index++) {
    const node = chain.nodes[index], rest = chain.rest[index];
    if (!node || !rest) continue;
    const progress = index / (chain.nodes.length - 1);
    const velocityX = (node.x - node.previousX) * damping;
    const velocityY = (node.y - node.previousY) * damping;
    node.previousX = node.x;
    node.previousY = node.y;
    const gust = (Math.sin(time * .85 + anchor.x * .006) * 22 + Math.sin(time * 1.9 + progress) * 6) * wind * progress;
    const goalX = goal ? rest.x + (goal.x - tipRest.x) * progress ** 2 : rest.x;
    const goalY = goal ? rest.y + (goal.y - tipRest.y) * progress ** 2 : rest.y;
    const stiffness = goal ? 105 : 48;
    node.x += velocityX + ((goalX - node.x) * stiffness + gust) * dt * dt;
    node.y += velocityY + (goalY - node.y) * stiffness * dt * dt;
  }
  for (let pass = 0; pass < 10; pass++) {
    for (let index = 1; index < chain.nodes.length; index++) {
      const a = chain.nodes[index - 1], b = chain.nodes[index], length = chain.lengths[index - 1];
      if (!a || !b || length === undefined) continue;
      const dx = b.x - a.x, dy = b.y - a.y;
      const distance = Math.max(.001, Math.hypot(dx, dy));
      const correction = (distance - length) / distance;
      if (index > 1) { a.x += dx * correction * .5; a.y += dy * correction * .5; }
      const share = index === 1 ? 1 : .5;
      b.x -= dx * correction * share;
      b.y -= dy * correction * share;
    }
    const tip = chain.nodes.at(-1);
    if (tip) Object.assign(tip, boundedTarget(chain, tip));
  }
  const a = chain.nodes.at(-2), b = chain.nodes.at(-1);
  if (a && b) {
    const angle = Math.atan2(b.y - a.y, b.x - a.x) + Math.PI / 2;
    chain.headVelocity += ((angle - chain.headAngle) * 42 - chain.headVelocity * 7.8) * dt;
    chain.headAngle += chain.headVelocity * dt;
  }
}

/** Attach an ornament at a fractional joint position, using the current tangent. */
export function attachment(chain: ElasticChain, progress: number) {
  const position = Math.max(0, Math.min(1, progress)) * (chain.nodes.length - 1);
  const index = Math.min(Math.floor(position), chain.nodes.length - 2);
  const a = chain.nodes[index], b = chain.nodes[index + 1];
  if (!a || !b) throw new Error('Missing attachment joints.');
  return { x: mix(a.x, b.x, position - index), y: mix(a.y, b.y, position - index), angle: Math.atan2(b.y - a.y, b.x - a.x) + Math.PI / 2 };
}

export function chainSnapshot(chain: ElasticChain) {
  const root = chain.nodes[0], tip = chain.nodes.at(-1), rest = chain.rest.at(-1);
  if (!root || !tip || !rest) throw new Error('Missing chain geometry.');
  return {
    root: { x: root.x, y: root.y },
    tip: { x: tip.x, y: tip.y },
    rest: { ...rest },
    maxPull: chain.maxPull,
    maxSegmentError: Math.max(...chain.nodes.slice(1).map((node, index) => {
      const previous = chain.nodes[index], length = chain.lengths[index];
      if (!previous || !length) return 0;
      return Math.abs(Math.hypot(node.x - previous.x, node.y - previous.y) / length - 1);
    })),
  };
}

export type Point = { x: number; y: number };
export type Size = { width: number; height: number };

export const TAU = Math.PI * 2;
export const clamp = (value: number, low = 0, high = 1) => Math.max(low, Math.min(high, value));
export const mix = (a: number, b: number, amount: number) => a + (b - a) * amount;

export function smooth(value: number) {
  const t = clamp(value);
  return t * t * (3 - 2 * t);
}

export function randomSource(seed: number) {
  let state = seed >>> 0;
  return () => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

export type RGB = readonly [number, number, number];

export function colour(from: RGB, to: RGB, amount: number, alpha = 1) {
  return `rgba(${from.map((channel, index) => Math.round(mix(channel, to[index] ?? channel, amount))).join(',')},${alpha})`;
}

.interactive-art-scene { position: relative; aspect-ratio: 1000 / 680; overflow: clip; }
.interactive-art-scene canvas { position: relative; display: block; width: 100%; height: 100%; touch-action: pan-y; }
.interactive-art-fallback { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.interactive-art-target { border: 1px solid transparent; cursor: grab; }
.interactive-art-target:active { cursor: grabbing; }
.interactive-art-target:focus-visible { outline: 2px solid #f1deb0; outline-offset: 3px; }
.interactive-art-target:disabled { cursor: default; }
@media (max-width: 520px) { .interactive-art-scene { aspect-ratio: 4 / 5; } }

"use client";

import { useEffect, useRef } from "react";
import { mountRootInfection, type RootInfectionController } from "./engine/runtime";
import type { RootInfectionProps as SimulationProps } from "./types";

export type RootInfectionProps = SimulationProps & {
  /** Stable callback. The controller is null after cleanup. */
  onReady?: (controller: RootInfectionController | null) => void;
};
export type { RootInfectionController } from "./engine/runtime";

/** The host owns layout. All animation work and temporary DOM belong to the runtime. */
export function RootInfection({
  inactivityDelay, fullInfectionDelay, maxRoots, maxParticles, growthSpeed,
  branchingProbability, physicsIterations, particleRadius, enableAudio = true, volume = 0.45,
  enableExplosion, enableRetraction, quality, className = "", onReady,
}: RootInfectionProps) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<RootInfectionController | null>(null);
  const audio = useRef({ enableAudio, volume });

  useEffect(() => {
    const element = host.current;
    if (!element) return;
    const instance = mountRootInfection(element, {
      inactivityDelay, fullInfectionDelay, maxRoots, maxParticles, growthSpeed,
      branchingProbability, physicsIterations, particleRadius,
      enableAudio: audio.current.enableAudio, volume: audio.current.volume,
      enableExplosion, enableRetraction, quality,
    });
    controller.current = instance;
    onReady?.(instance);
    return () => { instance.destroy(); controller.current = null; onReady?.(null); };
  }, [inactivityDelay, fullInfectionDelay, maxRoots, maxParticles, growthSpeed,
    branchingProbability, physicsIterations, particleRadius, enableExplosion, enableRetraction, quality, onReady]);

  useEffect(() => {
    audio.current = { enableAudio, volume };
    controller.current?.setAudio(enableAudio, volume);
  }, [enableAudio, volume]);

  return (
    <div ref={host} className={className} aria-label="Root Infection. Move the pointer to retract, click to scatter, or press Escape to clear."
      style={{ display: "grid", placeItems: "center", minHeight: 360, position: "relative", isolation: "isolate" }}>
      <p style={{ margin: 0, font: "inherit", fontSize: 13, letterSpacing: "0.02em" }}>don&apos;t move your mouse</p>
    </div>
  );
}

export type InfectionState =
  | "IDLE"
  | "AWAKENING"
  | "INFESTING"
  | "FULL_INFECTION"
  | "RETRACTING"
  | "EXPLODING";

export interface RootInfectionProps {
  /** Milliseconds of stillness before emergence. */
  inactivityDelay?: number;
  /** Milliseconds to full infection. Thin-root consolidation starts halfway through, after at least eight seconds. */
  fullInfectionDelay?: number;
  maxRoots?: number;
  maxParticles?: number;
  /** Growth speed multiplier. */
  growthSpeed?: number;
  /** Probability per growth interval, never per animation frame. */
  branchingProbability?: number;
  physicsIterations?: number;
  particleRadius?: number;
  enableAudio?: boolean;
  volume?: number;
  enableExplosion?: boolean;
  enableRetraction?: boolean;
  /** Auto preserves full detail and adjusts consolidation timing when frame cost grows. */
  quality?: "low" | "medium" | "high" | "auto";
  className?: string;
}

export type InfectionConfig = Required<Omit<RootInfectionProps, "className">>;
export type SoundEvent = "emerge" | "crawl" | "branch" | "whoosh" | "impact" | "debris";

export const FIXED_STEP = 1 / 60;

export const defaults: InfectionConfig = {
  inactivityDelay: 2400,
  fullInfectionDelay: 24000,
  maxRoots: Infinity,
  maxParticles: Infinity,
  growthSpeed: 1,
  branchingProbability: 0.075,
  physicsIterations: 5,
  particleRadius: 4.2,
  enableAudio: true,
  volume: 0.45,
  enableExplosion: true,
  enableRetraction: true,
  quality: "auto",
};

/** Validate once at the public boundary. Allocation limits are opt-in; thickness remains uncapped. */
export function configure(props: RootInfectionProps): InfectionConfig {
  const bounded = (value: number | undefined, fallback: number, min: number, max: number) =>
    Number.isFinite(value) ? Math.min(max, Math.max(min, value ?? fallback)) : fallback;
  const optionalLimit = (value: number | undefined, minimum: number) =>
    value === undefined || value === Infinity || !Number.isFinite(value) ? Infinity : Math.max(minimum, Math.round(value));
  return {
    inactivityDelay: bounded(props.inactivityDelay, defaults.inactivityDelay, 0, 600000),
    fullInfectionDelay: bounded(props.fullInfectionDelay, defaults.fullInfectionDelay, 1000, 600000),
    maxRoots: optionalLimit(props.maxRoots, 1),
    maxParticles: optionalLimit(props.maxParticles, 16),
    growthSpeed: bounded(props.growthSpeed, defaults.growthSpeed, 0.1, 4),
    branchingProbability: bounded(props.branchingProbability, defaults.branchingProbability, 0, 0.5),
    physicsIterations: Math.round(bounded(props.physicsIterations, defaults.physicsIterations, 1, 12)),
    particleRadius: bounded(props.particleRadius, defaults.particleRadius, 0.5, 8),
    enableAudio: props.enableAudio ?? defaults.enableAudio,
    volume: bounded(props.volume, defaults.volume, 0, 1),
    enableExplosion: props.enableExplosion ?? defaults.enableExplosion,
    enableRetraction: props.enableRetraction ?? defaults.enableRetraction,
    quality: props.quality ?? defaults.quality,
  };
}

import { SoundEngine } from "../audio/sound-engine";
import { RootRenderer } from "../rendering/renderer";
import { configure, FIXED_STEP, type InfectionState, type RootInfectionProps } from "../types";
import { PhysicsWorld } from "./world";

/** Owns one overlay, clock, input subscription, and audio context. No site state is required. */
export function mountRootInfection(host: HTMLElement, options: RootInfectionProps = {}) {
  const config = configure(options);
  const document = host.ownerDocument;
  const browser = document.defaultView;
  if (!browser) throw new Error("Root Infection requires a browser window.");
  const view = browser;
  const canvas = document.createElement("canvas");
  canvas.dataset.rootInfectionOverlay = "";
  canvas.setAttribute("aria-hidden", "true");
  Object.assign(canvas.style, { position: "fixed", inset: "0", width: "100%", height: "100%", pointerEvents: "none", zIndex: "2147483000", display: "none" });
  const world = new PhysicsWorld(config);
  const renderer = new RootRenderer(canvas);
  document.body.append(canvas);
  const backgroundCanvas = document.createElement("canvas");
  backgroundCanvas.width = 5; backgroundCanvas.height = 1;
  const backgroundContext = backgroundCanvas.getContext("2d", { willReadFrequently: true });
  const backgroundColors: string[] = [];
  const backgroundStyles = new Map<Element, string>();
  const luminances = new Float32Array(5);
  const samplePoints = [[0.12, 0.16], [0.88, 0.16], [0.5, 0.5], [0.12, 0.84], [0.88, 0.84]];
  let nextBackgroundRead = 0;
  const sound = new SoundEngine(config.enableAudio, config.volume);
  const events = new AbortController();
  const { signal } = events;
  const motion = view.matchMedia("(prefers-reduced-motion: reduce)");
  const frameTimes = new Float32Array(180), workTimes = new Float32Array(180);
  const physicsTimes = new Float32Array(180), geometryTimes = new Float32Array(180);
  const bodyTimes = new Float32Array(180), detailTimes = new Float32Array(180);
  let frame = 0, timer: ReturnType<typeof setTimeout> | undefined;
  let destroyed = false, inView = false, armed = true, geometryDirty = true;
  let x = 0, y = 0, movementX = 0, movementY = 0;
  let lastFrame = 0, accumulator = 0, frames = 0, fixedSteps = 0;
  const quality = config.quality === "low" ? 0 : config.quality === "medium" ? 1 : 2;
  let averageFrame = 16.67, averageWork = 0, droppedSeconds = 0;
  let state: InfectionState = "IDLE";
  let density = 1;
  const isIdle = () => world.state === "IDLE";
  let capture: HTMLElement | null = null;
  let captureId = -1;
  let scrollY = view.scrollY;
  world.iterations = Math.max(1, config.physicsIterations - (quality === 0 ? 3 : quality === 1 ? 1 : 0));
  world.collisionEvery = quality === 0 ? 3 : 1;

  /** Composite ancestor backgrounds at a few visible points. Canvas resolves CSS color spaces and alpha. */
  function refreshBackground() {
    const scheme = view.getComputedStyle(document.documentElement).colorScheme;
    const darkCanvas = scheme.includes("dark") && (!scheme.includes("light") || view.matchMedia("(prefers-color-scheme: dark)").matches);
    const c = backgroundContext;
    if (!c) { renderer.setBackgroundLuminance(darkCanvas ? 0 : 1); return; }
    c.fillStyle = darkCanvas ? "#121212" : "#fff";
    c.fillRect(0, 0, 5, 1);
    backgroundStyles.clear();
    for (let sample = 0; sample < samplePoints.length; sample++) {
      const point = samplePoints[sample];
      backgroundColors.length = 0;
      for (let element = document.elementFromPoint(world.width * point[0], world.height * point[1]); element; element = element.parentElement) {
        let color = backgroundStyles.get(element);
        if (color === undefined) { color = view.getComputedStyle(element).backgroundColor; backgroundStyles.set(element, color); }
        backgroundColors.push(color);
      }
      for (let layer = backgroundColors.length - 1; layer >= 0; layer--) {
        c.fillStyle = backgroundColors[layer]; c.fillRect(sample, 0, 1, 1);
      }
    }
    const pixels = c.getImageData(0, 0, 5, 1).data;
    const linear = (channel: number) => { const value = channel / 255; return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4; };
    for (let sample = 0; sample < 5; sample++) {
      const offset = sample * 4;
      luminances[sample] = linear(pixels[offset]) * 0.2126 + linear(pixels[offset + 1]) * 0.7152 + linear(pixels[offset + 2]) * 0.0722;
    }
    luminances.sort();
    renderer.setBackgroundLuminance(luminances[2]);
  }

  function publishState() {
    if (world.state === state) return;
    state = world.state;
    host.dataset.infectionState = state;
    if (state === "IDLE") {
      canvas.style.display = "none";
      sound.setInfestation(0);
      scheduleIdle();
    } else canvas.style.display = "block";
  }

  function resize() {
    const width = Math.max(1, view.innerWidth), height = Math.max(1, view.innerHeight);
    world.resize(width, height);
    density = quality === 2 ? view.devicePixelRatio || 1 : 1;
    renderer.resize(width, height, density);
    renderer.detail = quality;
    geometryDirty = true;
    nextBackgroundRead = 0;
    if (world.state === "IDLE") {
      const rect = host.getBoundingClientRect();
      x = rect.left + rect.width / 2; y = rect.top + rect.height / 2;
      movementX = x; movementY = y;
    }
  }

  function stopFrame() {
    view.cancelAnimationFrame(frame);
    frame = 0; lastFrame = 0; accumulator = 0;
  }

  function scheduleFrame() {
    if (!frame && !destroyed && !document.hidden && !motion.matches && world.state !== "IDLE") frame = view.requestAnimationFrame(tick);
  }

  function clearIdle() {
    if (timer !== undefined) clearTimeout(timer);
    timer = undefined;
  }

  function scheduleIdle() {
    clearIdle();
    if (destroyed || document.hidden || motion.matches || !inView || !armed || world.state !== "IDLE") return;
    timer = setTimeout(() => {
      timer = undefined;
      if (destroyed || document.hidden || motion.matches || !inView || !armed || world.state !== "IDLE") return;
      world.field.refresh(document, host, world.width, world.height);
      refreshBackground(); nextBackgroundRead = performance.now() + 1000;
      geometryDirty = false;
      world.awaken(x, y);
      movementX = x; movementY = y;
      publishState();
      scheduleFrame();
    }, config.inactivityDelay);
  }

  function adaptGrowth() {
    if (config.quality !== "auto" || frames % 30 !== 0) return;
    if (averageWork > 5.5 || averageFrame > 20) world.consolidateEarly();
  }

  function tick(now: number) {
    frame = 0;
    if (destroyed || document.hidden || motion.matches || world.state === "IDLE") return;
    const start = performance.now();
    if (now >= nextBackgroundRead) { refreshBackground(); nextBackgroundRead = now + 1000; }
    const delta = lastFrame ? Math.max(0, (now - lastFrame) / 1000) : FIXED_STEP;
    lastFrame = now;
    droppedSeconds += Math.max(0, delta - 0.1);
    accumulator += Math.min(0.1, delta);
    if (geometryDirty) { world.field.refresh(document, host, world.width, world.height); geometryDirty = false; }
    const stepBudget = quality === 0 ? 1 : 6;
    if (accumulator > FIXED_STEP * stepBudget) {
      droppedSeconds += accumulator - FIXED_STEP * stepBudget;
      accumulator = FIXED_STEP * stepBudget;
    }
    let steps = 0;
    const physicsStart = performance.now();
    while (accumulator >= FIXED_STEP && steps < stepBudget) {
      world.step();
      accumulator -= FIXED_STEP;
      steps++; fixedSteps++;
      if (isIdle()) break;
    }
    const physicsMs = performance.now() - physicsStart;
    world.drainSounds(playSound);
    renderer.paint(world, Math.min(1, accumulator / FIXED_STEP));
    if (frames % 30 === 0) sound.setInfestation(world.state === "INFESTING" || world.state === "FULL_INFECTION" ? Math.max(0, world.age / (config.fullInfectionDelay / 1000) - 0.25) : 0);
    const work = performance.now() - start;
    frameTimes[frames % frameTimes.length] = delta * 1000;
    workTimes[frames % workTimes.length] = work;
    physicsTimes[frames % physicsTimes.length] = physicsMs;
    geometryTimes[frames % geometryTimes.length] = renderer.timings.geometryMs;
    bodyTimes[frames % bodyTimes.length] = renderer.timings.bodyMs;
    detailTimes[frames % detailTimes.length] = renderer.timings.detailMs;
    averageFrame += (Math.min(100, delta * 1000) - averageFrame) * 0.025;
    averageWork += (work - averageWork) * 0.025;
    frames++;
    adaptGrowth();
    publishState();
    scheduleFrame();
  }

  function playSound(event: Parameters<SoundEngine["play"]>[0]) {
    sound.play(event, world.originX / world.width * 2 - 1);
  }

  function outcome(next: "RETRACTING" | "EXPLODING", px: number, py: number) {
    if (!world.react(next, px, py)) return;
    sound.setInfestation(0);
    world.drainSounds(playSound);
    publishState();
    scheduleFrame();
  }

  function inside(px: number, py: number) {
    const rect = host.getBoundingClientRect();
    return px >= rect.left && px <= rect.right && py >= rect.top && py <= rect.bottom;
  }

  document.addEventListener("pointermove", (event) => {
    if (event.pointerType === "touch" || !event.isPrimary) return;
    if (world.state === "RETRACTING" || world.state === "EXPLODING") {
      movementX = x = event.clientX; movementY = y = event.clientY;
      armed = inside(x, y);
      return;
    }
    if (world.held >= 0) {
      world.moveHeld(event.clientX, event.clientY);
      movementX = x = event.clientX; movementY = y = event.clientY;
      return;
    }
    if (event.shiftKey && world.state !== "IDLE") {
      movementX = x = event.clientX; movementY = y = event.clientY;
      world.disturb(x, y);
      return;
    }
    const distance = Math.hypot(event.clientX - movementX, event.clientY - movementY);
    if (distance < 6) return;
    x = event.clientX; y = event.clientY;
    movementX = x; movementY = y;
    armed = inside(x, y);
    if (world.state === "IDLE") {
      scheduleIdle();
    } else if (config.enableRetraction) outcome("RETRACTING", x, y);
  }, { passive: true, signal });

  document.addEventListener("pointerdown", (event) => {
    if (event.isTrusted) void sound.unlock();
    if (world.state === "RETRACTING" || world.state === "EXPLODING" || event.button !== 0) return;
    if (event.shiftKey && world.hold(event.clientX, event.clientY)) {
      if (event.target instanceof HTMLElement) {
        capture = event.target; captureId = event.pointerId;
        capture.setPointerCapture(captureId);
      }
      event.preventDefault();
      return;
    }
    if (world.state !== "IDLE") {
      if (config.enableExplosion) {
        // Schedule audio after resume resolves without delaying the physical impulse.
        outcome("EXPLODING", event.clientX, event.clientY);
        if (event.isTrusted) void sound.unlock().then(() => {
          if (!destroyed && world.state === "EXPLODING") sound.play("impact", event.clientX / world.width * 2 - 1);
        });
      }
    } else {
      x = event.clientX; y = event.clientY;
      movementX = x; movementY = y;
      armed = inside(x, y);
      scheduleIdle();
    }
  }, { signal });

  const release = () => {
    world.release();
    if (capture?.hasPointerCapture(captureId)) capture.releasePointerCapture(captureId);
    capture = null; captureId = -1;
  };
  document.addEventListener("pointerup", release, { signal });
  document.addEventListener("pointercancel", release, { signal });
  document.addEventListener("lostpointercapture", release, { signal });

  document.addEventListener("keydown", (event) => {
    if (event.isTrusted) void sound.unlock();
    if (["Shift", "Alt", "Control", "Meta"].includes(event.key)) return;
    if (event.key === "Escape") {
      release();
      world.reset(); renderer.paint(world, 1); stopFrame(); publishState();
      armed = false; clearIdle();
    } else if (world.state === "IDLE") { armed = false; clearIdle(); }
    else if (config.enableRetraction) outcome("RETRACTING", x, y);
  }, { signal });

  document.addEventListener("scroll", () => {
    geometryDirty = true;
    nextBackgroundRead = 0;
    world.pushFromScroll(view.scrollY - scrollY);
    scrollY = view.scrollY;
  }, { passive: true, capture: true, signal });
  view.addEventListener("resize", resize, { passive: true, signal });
  document.addEventListener("visibilitychange", () => {
    clearIdle(); stopFrame();
    release();
    sound.setHidden(document.hidden);
    if (!document.hidden) { geometryDirty = true; nextBackgroundRead = 0; scheduleIdle(); scheduleFrame(); }
  }, { signal });
  motion.addEventListener("change", () => {
    clearIdle(); stopFrame();
    release();
    if (motion.matches) {
      world.reset(); renderer.paint(world, 1); sound.setHidden(true); publishState();
    } else { sound.setHidden(document.hidden); scheduleIdle(); }
  }, { signal });
  const intersection = new IntersectionObserver((entries) => {
    inView = entries.some((entry) => entry.isIntersecting);
    scheduleIdle();
  }, { threshold: 0.05 });
  const layout = new ResizeObserver(() => { geometryDirty = true; });
  intersection.observe(host); layout.observe(document.body);
  host.dataset.infectionState = "IDLE";
  resize();
  if (motion.matches) sound.setHidden(true);

  return {
    reset() { if (destroyed) return; world.reset(); renderer.paint(world, 1); stopFrame(); publishState(); scheduleIdle(); },
    setAudio(enabled: boolean, volume = config.volume) { if (!destroyed) sound.setOptions(enabled, volume); },
    snapshot() {
      const count = Math.min(frames, frameTimes.length);
      const intervals = Array.from(frameTimes.subarray(0, count)).sort((a, b) => a - b);
      const work = Array.from(workTimes.subarray(0, count)).sort((a, b) => a - b);
      const physics = Array.from(physicsTimes.subarray(0, count)).sort((a, b) => a - b);
      const geometry = Array.from(geometryTimes.subarray(0, count)).sort((a, b) => a - b);
      const body = Array.from(bodyTimes.subarray(0, count)).sort((a, b) => a - b);
      const detail = Array.from(detailTimes.subarray(0, count)).sort((a, b) => a - b);
      const median = intervals[Math.floor(count / 2)] ?? 0;
      return { ...world.inspect(), running: Boolean(frame), destroyed, hidden: document.hidden, reducedMotion: motion.matches, armed, inView,
        viewport: { width: world.width, height: world.height, density }, audio: sound.inspect(), rendering: renderer.inspect(),
        performance: { renderedFrames: frames, fixedSteps, fps: median ? 1000 / median : 0, medianFrameMs: median,
          p95FrameMs: intervals[Math.floor(count * 0.95)] ?? 0, medianWorkMs: work[Math.floor(count / 2)] ?? 0,
          p95WorkMs: work[Math.floor(count * 0.95)] ?? 0,
          medianPhysicsMs: physics[Math.floor(count / 2)] ?? 0, medianGeometryMs: geometry[Math.floor(count / 2)] ?? 0,
          medianBodyMs: body[Math.floor(count / 2)] ?? 0, medianDetailMs: detail[Math.floor(count / 2)] ?? 0,
          quality, droppedSeconds } };
    },
    destroy() {
      if (destroyed) return;
      destroyed = true;
      clearIdle(); stopFrame(); events.abort();
      release();
      intersection.disconnect(); layout.disconnect();
      sound.dispose(); renderer.dispose(); world.reset(); canvas.remove();
      backgroundStyles.clear(); backgroundColors.length = 0;
      backgroundCanvas.width = backgroundCanvas.height = 0;
      delete host.dataset.infectionState;
    },
  };
}

export type RootInfectionController = ReturnType<typeof mountRootInfection>;

import { FIXED_STEP, type InfectionConfig, type InfectionState, type SoundEvent } from "../types";
import { CollisionField } from "./collision-field";
import { ParticlePool } from "./particles";
import { SpatialHash } from "./spatial-hash";

const TAU = Math.PI * 2;
const SEGMENT = 10;
const INITIAL_SEGMENTS = 180;
const COVERAGE_CELL = 96;
const isGrowing = (state: InfectionState) => state === "AWAKENING" || state === "INFESTING" || state === "FULL_INFECTION";

function makeRoot() {
  return {
    ids: new Int32Array(INITIAL_SEGMENTS),
    pathX: new Float32Array(INITIAL_SEGMENTS),
    pathY: new Float32Array(INITIAL_SEGMENTS),
    pathDistance: new Float32Array(INITIAL_SEGMENTS),
    count: 0, depth: 0, parentRoot: -1, parentJoint: -1,
    angle: 0, phase: 0, speed: 1, thickness: 1, targetX: 0, targetY: 0,
    nextGrowth: 0, nextTurn: 0, limit: 100, worm: false, born: 0, merging: false,
    surfaceUntil: 0, surfaceDirection: 1, children: 0,
    mergeAge: 0, mergeJoint: 0, mergedVolume: 0, mergeTarget: -1,
    retained: false, width: 0, score: 0, bulk: 1, centerX: 0, centerY: 0, targetReached: false, exposure: 1, totalLength: 0,
  };
}

/** React-free fixed-step solver. Roots share branch particles rather than duplicating joints. */
export class PhysicsWorld {
  readonly particles: ParticlePool;
  readonly hash: SpatialHash;
  readonly field = new CollisionField();
  readonly roots: ReturnType<typeof makeRoot>[];
  rootCount = 0;
  state: InfectionState = "IDLE";
  age = 0;
  stateAge = 0;
  width = 1;
  height = 1;
  originX = 0;
  originY = 0;
  branchCount = 0;
  wormCount = 0;
  recycledBranches = 0;
  absorbedVolume = 0;
  growthFrontier = 0;
  pressure = 0;
  maturation: "SPREADING" | "CONSOLIDATING" | "SWELLING" = "SPREADING";
  culledRoots = 0;
  private consolidationAge = 0;
  private nextCull = 0;
  private nextFork = 0;
  private coverageColumns = 1;
  private coverageRows = 1;
  private coverage = new Uint8Array(1);
  private coverageOwner = new Int32Array(1);
  private reservations = new Uint8Array(1);
  coveredCells = 0;
  wrappedTips = 0;
  held = -1;
  private heldMass = 1;
  private heldX = 0;
  private heldY = 0;
  private gust = 0;
  private nextRecycle = 0;
  iterations: number;
  collisionEvery = 1;
  surfaceEvery = 1;
  private tick = 0;
  private nextSpawn = 0;
  private nextCrawl = 0;
  private seed = 13486;
  private longestPath = 0;
  private deepestGeneration = 0;
  private readonly soundQueue: SoundEvent[] = [];

  constructor(readonly config: InfectionConfig) {
    this.particles = new ParticlePool(config.maxParticles);
    this.hash = new SpatialHash(this.particles.capacity);
    this.roots = Array.from({ length: Math.min(64, config.maxRoots) }, makeRoot);
    this.iterations = config.physicsIterations;
  }

  private random() {
    this.seed = (Math.imul(this.seed, 1664525) + 1013904223) >>> 0;
    return this.seed / 4294967296;
  }

  resize(width: number, height: number) {
    const scaleX = width / this.width, scaleY = height / this.height;
    const p = this.particles;
    for (let slot = p.used - 1; slot >= 0; slot--) {
      const id = p.active[slot];
      p.x[id] *= scaleX; p.previousX[id] *= scaleX; p.renderX[id] *= scaleX;
      p.y[id] *= scaleY; p.previousY[id] *= scaleY; p.renderY[id] *= scaleY;
    }
    for (let index = 0; index < this.rootCount; index++) {
      const root = this.roots[index];
      root.targetX *= scaleX; root.targetY *= scaleY;
      root.targetReached = false;
      for (let joint = 0; joint < root.count; joint++) {
        root.pathX[joint] *= scaleX; root.pathY[joint] *= scaleY;
      }
    }
    this.originX *= scaleX; this.originY *= scaleY;
    this.width = Math.max(1, width); this.height = Math.max(1, height);
    this.hash.resize(this.width, this.height);
    this.coverageColumns = Math.ceil(this.width / COVERAGE_CELL);
    this.coverageRows = Math.ceil(this.height / COVERAGE_CELL);
    this.coverage = new Uint8Array(this.coverageColumns * this.coverageRows);
    this.coverageOwner = new Int32Array(this.coverage.length);
    this.reservations = new Uint8Array(this.coverage.length);
    this.nextFork = 0; this.coveredCells = 0;
    if (this.state === "RETRACTING") { this.capturePaths(); this.stateAge = 0; }
  }

  awaken(x: number, y: number) {
    if (this.state !== "IDLE") return;
    this.originX = Math.min(this.width - 2, Math.max(2, x));
    this.originY = Math.min(this.height - 2, Math.max(2, y));
    this.age = this.stateAge = this.nextSpawn = this.nextCrawl = 0;
    this.state = "AWAKENING";
    this.emit("emerge");
  }

  /** The first outcome owns the transition until every particle is removed. */
  react(outcome: "RETRACTING" | "EXPLODING", x = this.originX, y = this.originY) {
    if (!isGrowing(this.state)) return false;
    this.release();
    this.field.clearReactions();
    this.state = outcome;
    this.stateAge = 0;
    if (outcome === "RETRACTING") {
      this.capturePaths();
      this.emit("whoosh");
    } else {
      const p = this.particles;
      for (let index = 0; index < this.rootCount; index++) {
        const root = this.roots[index];
        for (let joint = 0; joint < root.count; joint++) {
          const id = root.ids[joint];
          // Leave two-joint ligaments. Different impulses make them tumble.
          p.connected[id] = joint > 0 && joint % 3 !== 0 ? 1 : 0;
          p.inverseMass[id] = 1;
          const dx = p.x[id] - x, dy = p.y[id] - y;
          const distance = Math.max(16, Math.hypot(dx, dy));
          const impulse = 220 + 280 * Math.exp(-distance / 500) + this.random() * 180;
          const spin = (joint % 3 - 1) * 90;
          p.previousX[id] = p.x[id] - (dx / distance * impulse - dy / distance * spin) * FIXED_STEP;
          p.previousY[id] = p.y[id] - (dy / distance * impulse + dx / distance * spin - 300) * FIXED_STEP;
        }
      }
      // Debris uses the same pool and has no distance constraints.
      const debris = Math.min(100, p.capacity - p.used);
      for (let index = 0; index < debris; index++) {
        const source = Math.floor(this.random() * Math.max(1, p.count - index));
        const id = p.acquire(p.x[source] ?? x, p.y[source] ?? y, 0.5 + this.random() * 1.5, -1);
        const angle = this.random() * TAU, impulse = 150 + this.random() * 450;
        p.inverseMass[id] = 1;
        p.previousX[id] -= Math.cos(angle) * impulse * FIXED_STEP;
        p.previousY[id] -= (Math.sin(angle) * impulse - 200) * FIXED_STEP;
      }
      this.emit("impact");
    }
    return true;
  }

  reset() {
    this.release();
    this.field.clearReactions();
    this.particles.reset();
    this.rootCount = this.branchCount = this.wormCount = 0;
    this.recycledBranches = this.wrappedTips = this.absorbedVolume = this.growthFrontier = this.pressure = 0;
    this.nextRecycle = this.gust = this.deepestGeneration = this.nextCull = this.consolidationAge = this.culledRoots = 0;
    this.nextFork = this.coveredCells = 0;
    this.coverage.fill(0);
    this.reservations.fill(0);
    this.maturation = "SPREADING";
    this.state = "IDLE";
    this.age = this.stateAge = 0;
    this.soundQueue.length = 0;
  }

  private emit(event: SoundEvent) {
    if (this.soundQueue.length < 12 && !this.soundQueue.includes(event)) this.soundQueue.push(event);
  }

  drainSounds(play: (event: SoundEvent) => void) {
    for (let index = 0; index < this.soundQueue.length; index++) play(this.soundQueue[index]);
    this.soundQueue.length = 0;
  }

  private chooseTarget(root: ReturnType<typeof makeRoot>, index: number) {
    // Primary roots seek the perimeter. Branches distribute through the interior.
    const sequence = index + Math.floor(this.age / 8) * 13;
    root.targetX = (0.04 + ((sequence * 0.61803398875 + 0.21) % 1) * 0.92) * this.width;
    root.targetY = (0.04 + ((sequence * 0.754877666 + 0.37) % 1) * 0.92) * this.height;
    if (root.depth === 0) {
      const edge = index % 4;
      const reach = this.pressure * 60;
      if (edge === 0) root.targetX = 12 - reach;
      if (edge === 1) root.targetY = 12 - reach;
      if (edge === 2) root.targetX = this.width - 12 + reach;
      if (edge === 3) root.targetY = this.height - 12 + reach;
    }
  }

  private birthSize() { return 1 + this.age * 0.04; }

  private spawn(parentRoot = -1, parentJoint = -1) {
    const p = this.particles;
    const mature = this.maturation !== "SPREADING";
    const allowed = Math.min(this.config.maxRoots, 6 + Math.floor(this.age * 6));
    let index = 0;
    while (index < this.rootCount && this.roots[index].count > 0) index++;
    if (index >= allowed || p.used + 3 >= p.limit) return;
    p.ensureCapacity(p.used + 3);
    if (index >= this.roots.length) this.roots.push(makeRoot());
    if (parentRoot < 0 && (this.rootCount >= Math.min(6, this.config.maxRoots) || index < this.rootCount)) {
      // Fill the shallowest generation, distributing births among its siblings.
      let fewestChildren = 5;
      for (let offset = 0; offset < this.rootCount; offset++) {
        const candidate = (index + offset + 7) % this.rootCount;
        const parent = this.roots[candidate];
        if (candidate !== index && parent.count > 12 && !parent.merging && !parent.worm && parent.depth === this.growthFrontier && parent.children < fewestChildren) {
          parentRoot = candidate; fewestChildren = parent.children;
          parentJoint = parent.ids[Math.min(parent.count - 5, 8 + parent.children * 13)];
        }
      }
      if (parentRoot < 0) return;
    }
    if (parentRoot >= 0 && (this.roots[parentRoot].depth !== this.growthFrontier || this.roots[parentRoot].children >= 4)) return;
    const root = this.roots[index];
    root.count = 0;
    root.depth = parentRoot < 0 ? 0 : this.roots[parentRoot].depth + 1;
    this.deepestGeneration = Math.max(this.deepestGeneration, root.depth);
    root.parentRoot = parentRoot;
    root.parentJoint = parentJoint;
    root.phase = this.random() * TAU;
    root.thickness = parentRoot < 0 ? 0.7 + this.random() * 1.4 : this.roots[parentRoot].thickness * (0.5 + this.random() * 0.35);
    if (mature && parentJoint >= 0) root.thickness = Math.max(root.thickness, p.radius[parentJoint] * 0.6 / (this.config.particleRadius * this.birthSize()));
    root.speed = 0.6 + this.random() * 0.9;
    root.limit = root.depth === 0 ? Math.floor(125 + this.random() * 50)
      : root.depth === 1 ? Math.floor(40 + this.random() * 45)
      : root.depth === 2 ? Math.floor(16 + this.random() * 20) : Math.floor(8 + this.random() * 12);
    root.nextGrowth = this.age + 0.08;
    root.nextTurn = this.age + 1 + this.random() * 2;
    root.worm = false;
    root.born = this.age;
    root.merging = false;
    root.children = root.mergeAge = root.mergedVolume = 0;
    root.mergeTarget = -1; root.retained = mature; root.bulk = 1; root.targetReached = false;
    root.exposure = 1; root.width = root.score = root.totalLength = 0;
    root.surfaceUntil = 0;
    root.surfaceDirection = this.random() < 0.5 ? -1 : 1;
    if (parentJoint >= 0) {
      root.ids[root.count++] = parentJoint;
      const previous = p.parent[parentJoint];
      const angle = previous < 0 ? root.phase : Math.atan2(p.y[parentJoint] - p.y[previous], p.x[parentJoint] - p.x[previous]);
      root.angle = angle + (this.random() < 0.5 ? -1 : 1) * (0.5 + this.random() * 0.8);
      this.branchCount++;
      this.roots[parentRoot].children++;
      this.emit("branch");
    } else {
      root.angle = index * 2.3999632297 + root.phase * 0.15;
      const id = p.acquire(this.originX, this.originY, this.config.particleRadius * root.thickness * this.birthSize(), index);
      p.born[id] = this.age;
      root.ids[root.count++] = id;
    }
    this.chooseTarget(root, index);
    this.rootCount = Math.max(this.rootCount, index + 1);
    this.extend(root, index, false);
    return index;
  }

  private extend(root: ReturnType<typeof makeRoot>, index: number, reserveForBirth = true) {
    const reserve = reserveForBirth ? Math.min(40, Math.floor(this.particles.capacity * 0.02)) : 0;
    if (root.count >= root.limit || this.particles.used >= this.particles.limit - reserve) return;
    this.particles.ensureCapacity(this.particles.used + reserve + 1);
    if (root.count === root.ids.length) {
      const capacity = root.ids.length * 2;
      const ids = new Int32Array(capacity); ids.set(root.ids); root.ids = ids;
      const x = new Float32Array(capacity); x.set(root.pathX); root.pathX = x;
      const y = new Float32Array(capacity); y.set(root.pathY); root.pathY = y;
      const distance = new Float32Array(capacity); distance.set(root.pathDistance); root.pathDistance = distance;
    }
    const p = this.particles, previous = root.ids[root.count - 1];
    const taper = Math.max(0.24, 1 - root.count / root.limit * 0.7);
    const birthSize = this.birthSize();
    const id = p.acquire(p.x[previous] + Math.cos(root.angle) * 0.7, p.y[previous] + Math.sin(root.angle) * 0.7,
      this.config.particleRadius * root.thickness * taper * birthSize, index, previous);
    if (id < 0) return;
    p.born[id] = this.age;
    root.ids[root.count++] = id;
    root.totalLength += SEGMENT * (1 + this.age * 0.012);
  }

  /** Every shallow parent fills its four branch slots before a deeper generation opens. */
  private updateFrontier() {
    for (let index = 0; index < this.rootCount; index++) this.roots[index].children = 0;
    for (let index = 0; index < this.rootCount; index++) {
      const root = this.roots[index];
      if (root.count > 1 && root.parentJoint >= 0) this.roots[root.parentRoot].children++;
    }
    this.growthFrontier = this.deepestGeneration;
    for (let index = 0; index < this.rootCount; index++) {
      const root = this.roots[index];
      if (root.count > 1 && !root.merging && !root.worm && root.children < 4) this.growthFrontier = Math.min(this.growthFrontier, root.depth);
    }
  }

  private recycle() {
    if ((this.particles.used < this.particles.limit * 0.92 && this.rootCount < this.config.maxRoots && this.age < 20) || this.age < this.nextRecycle) return;
    this.nextRecycle = this.age + 1.8;
    let candidate = -1, oldest = -Infinity, merging = 0;
    for (let index = 0; index < this.rootCount; index++) {
      const root = this.roots[index];
      if (root.merging) merging++;
      if (root.count < 3 || root.merging || root.worm || root.depth < 1 || root.children > 0 || this.age - root.born < 8 || root.ids.includes(this.held)) continue;
      if (this.age - root.born > oldest) { oldest = this.age - root.born; candidate = index; }
    }
    if (candidate < 0 || merging >= 6) return;
    const parent = this.roots[candidate].parentRoot;
    // Several small siblings coalesce onto the same living trunk together.
    let selected = 0;
    for (let index = 0; index < this.rootCount && selected < 3; index++) {
      const root = this.roots[index];
      if (root.parentRoot !== parent || root.count < 3 || root.merging || root.worm || root.children > 0 || this.age - root.born < 8 || root.ids.includes(this.held)) continue;
      this.beginMerge(root, parent);
      selected++;
    }
    this.emit("crawl");
  }

  private matureRootTarget() { return Math.max(8, Math.ceil(Math.sqrt(this.width * this.height) / 100)); }

  /** Keep substantial forks and their supporting joints while absorbing the thin early network. */
  private beginConsolidation() {
    const p = this.particles;
    let active = 0, widest = 0;
    for (let index = 0; index < this.rootCount; index++) {
      const root = this.roots[index];
      root.retained = false; root.score = 0;
      if (root.count < 2 || root.merging) continue;
      let area = 0, length = 0;
      for (let joint = 1; joint < root.count; joint++) {
        const id = root.ids[joint], segment = p.length[id];
        area += p.radius[id] * segment; length += segment;
      }
      root.width = area / Math.max(1, length);
      root.totalLength = length;
      root.score = root.width * (0.6 + Math.min(1, length / Math.hypot(this.width, this.height))) / (1 + root.depth * 0.25);
      const middle = root.ids[Math.floor(root.count / 2)];
      root.centerX = p.x[middle]; root.centerY = p.y[middle];
      widest = Math.max(widest, root.width); active++;
    }
    // Keep a perimeter trunk in each direction, then the largest remaining bodies.
    let retained = 0;
    for (let edge = 0; edge < 4; edge++) {
      let best = -1;
      for (let index = edge; index < this.rootCount; index += 4) {
        const root = this.roots[index];
        if (root.count > 1 && root.depth === 0 && !root.merging && (best < 0 || root.score > this.roots[best].score)) best = index;
      }
      if (best >= 0) { this.roots[best].retained = true; retained++; }
    }
    const target = Math.min(active, this.config.branchingProbability > 0
      ? Math.min(this.matureRootTarget(), Math.max(8, Math.ceil(active * 0.45))) : 4);
    while (retained < target) {
      let best = -1;
      for (let index = 0; index < this.rootCount; index++) {
        const root = this.roots[index];
        if (root.count > 1 && !root.retained && !root.merging && (best < 0 || root.score > this.roots[best].score)) best = index;
      }
      if (best < 0) break;
      this.roots[best].retained = true; retained++;
    }
    for (let index = 0; index < this.rootCount; index++) {
      if (!this.roots[index].retained) continue;
      let parent = this.roots[index].parentJoint >= 0 ? this.roots[index].parentRoot : -1;
      while (parent >= 0) {
        const root = this.roots[parent]; root.retained = true;
        parent = root.parentJoint >= 0 ? root.parentRoot : -1;
      }
    }
    for (let index = 0; index < this.rootCount; index++) {
      const root = this.roots[index];
      if (root.retained) {
        root.bulk = Math.max(1, widest * 0.8 / Math.max(0.1, root.width));
        root.targetReached = false;
        if (root.depth === 0) this.chooseTarget(root, index);
      }
    }
    this.maturation = "CONSOLIDATING";
    this.consolidationAge = this.age;
    this.nextCull = this.age;
    this.nextFork = this.age + 2;
  }

  /** Frame cost can advance the same growth transition without changing visual fidelity. */
  consolidateEarly() {
    if (this.maturation === "SPREADING" && this.age >= 8 && isGrowing(this.state)) this.beginConsolidation();
  }

  private consolidate() {
    if (this.age < this.nextCull) return;
    this.nextCull = this.age + 0.3;
    this.updateFrontier();
    let remaining = 0, merging = 0;
    for (let index = 0; index < this.rootCount; index++) {
      const root = this.roots[index];
      if (root.count > 1 && !root.retained) remaining++;
      if (root.merging) merging++;
    }
    if (!remaining) { this.maturation = "SWELLING"; return; }
    let started = 0;
    for (let index = 0; index < this.rootCount && started < 4 && merging < 12; index++) {
      const root = this.roots[index];
      if (root.count < 2 || root.retained || root.merging || root.children > 0 || (this.held >= 0 && (this.particles.root[this.held] === index || root.parentJoint === this.held))) continue;
      let target = root.parentJoint >= 0 ? root.parentRoot : -1;
      if (target < 0) {
        let nearest = Infinity;
        for (let candidate = 0; candidate < this.rootCount; candidate++) {
          const trunk = this.roots[candidate];
          if (!trunk.retained || trunk.count < 2) continue;
          const dx = root.centerX - trunk.centerX, dy = root.centerY - trunk.centerY;
          const distance = dx * dx + dy * dy;
          if (distance < nearest) { nearest = distance; target = candidate; }
        }
      }
      if (target < 0 || this.roots[target].merging) continue;
      this.beginMerge(root, target); started++; merging++;
    }
    if (started) this.emit("crawl");
  }

  /** Coarse tissue occupancy is refreshed at fork intervals, never during rendering. */
  private measureCoverage() {
    const p = this.particles;
    this.coverage.fill(0); this.coverageOwner.fill(-1); this.reservations.fill(0);
    for (let index = 0; index < this.rootCount; index++) {
      const root = this.roots[index];
      if (!root.retained || root.merging || root.count < 2) continue;
      if (!root.targetReached) {
        const column = Math.max(0, Math.min(this.coverageColumns - 1, Math.floor(root.targetX / COVERAGE_CELL)));
        const row = Math.max(0, Math.min(this.coverageRows - 1, Math.floor(root.targetY / COVERAGE_CELL)));
        this.reservations[row * this.coverageColumns + column] = 1;
      }
      let width = 0, length = 0, samples = 0;
      for (let joint = 1; joint < root.count; joint += 4) {
        const id = root.ids[joint], radius = p.radius[id] + 12;
        width += p.radius[id]; length += p.length[id]; samples++;
        const left = Math.max(0, Math.floor((p.x[id] - radius) / COVERAGE_CELL));
        const right = Math.min(this.coverageColumns - 1, Math.floor((p.x[id] + radius) / COVERAGE_CELL));
        const top = Math.max(0, Math.floor((p.y[id] - radius) / COVERAGE_CELL));
        const bottom = Math.min(this.coverageRows - 1, Math.floor((p.y[id] + radius) / COVERAGE_CELL));
        for (let row = top; row <= bottom; row++) for (let column = left; column <= right; column++) {
          const cell = row * this.coverageColumns + column;
          if (this.coverageOwner[cell] === index) continue;
          const x = Math.min(this.width - 8, (column + 0.5) * COVERAGE_CELL);
          const y = Math.min(this.height - 8, (row + 0.5) * COVERAGE_CELL);
          if ((x - p.x[id]) ** 2 + (y - p.y[id]) ** 2 > radius * radius) continue;
          this.coverageOwner[cell] = index;
          if (this.coverage[cell] < 255) this.coverage[cell]++;
        }
      }
      root.width = width / Math.max(1, samples);
      root.totalLength = length * (root.count - 1) / Math.max(1, samples);
      const middle = root.ids[Math.floor(root.count / 2)];
      root.centerX = p.x[middle]; root.centerY = p.y[middle];
    }
    this.coveredCells = 0;
    for (const count of this.coverage) if (count) this.coveredCells++;
    for (let index = 0; index < this.rootCount; index++) {
      const root = this.roots[index];
      if (!root.retained || root.count < 2) continue;
      let unique = 0, samples = 0;
      for (let joint = 1; joint < root.count; joint += 4) {
        const id = root.ids[joint];
        const column = Math.max(0, Math.min(this.coverageColumns - 1, Math.floor(p.x[id] / COVERAGE_CELL)));
        const row = Math.max(0, Math.min(this.coverageRows - 1, Math.floor(p.y[id] / COVERAGE_CELL)));
        if (this.coverage[row * this.coverageColumns + column] <= 1) unique++;
        samples++;
      }
      root.exposure = unique / Math.max(1, samples);
    }
  }

  /** A few thick forks keep occupying open space; crowded leaves supply their parents with tissue. */
  private renewForks() {
    if (this.age < this.nextFork || this.config.branchingProbability === 0) return;
    this.nextFork = this.age + 2.2 / Math.sqrt(this.config.growthSpeed);
    this.updateFrontier(); this.measureCoverage();
    let target = -1, furthest = -1, retained = 0, crowded = -1, score = -1;
    for (let index = 0; index < this.rootCount; index++) {
      const root = this.roots[index];
      if (!root.retained || root.merging || root.count < 2) continue;
      retained++;
      if (root.depth === 0 || root.worm || root.children > 0 || this.age - root.born < 10 || root.exposure > 0.4 || (this.held >= 0 && this.particles.root[this.held] === index)) continue;
      const value = (1 - root.exposure) * (this.age - root.born) / (1 + root.width);
      if (value > score) { crowded = index; score = value; }
    }
    for (let cell = 0; cell < this.coverage.length; cell++) {
      if (this.coverage[cell] || this.reservations[cell]) continue;
      const x = Math.min(this.width - 8, (cell % this.coverageColumns + 0.5) * COVERAGE_CELL);
      const y = Math.min(this.height - 8, (Math.floor(cell / this.coverageColumns) + 0.5) * COVERAGE_CELL);
      this.field.sample(x, y);
      if (this.field.distance < 18) continue;
      const distance = (x - this.originX) ** 2 + (y - this.originY) ** 2;
      if (distance > furthest) { furthest = distance; target = cell; }
    }
    if (this.random() > Math.min(1, this.config.branchingProbability / 0.075)) return;
    const desired = this.matureRootTarget();
    const absorb = retained >= desired && crowded >= 0;
    if (!absorb && retained >= desired + 4) return;
    let x: number, y: number;
    if (target >= 0) {
      x = Math.min(this.width - 8, (target % this.coverageColumns + 0.5) * COVERAGE_CELL);
      y = Math.min(this.height - 8, (Math.floor(target / this.coverageColumns) + 0.5) * COVERAGE_CELL);
    } else {
      if (this.pressure <= 0 || crowded < 0) return;
      // Fully occupied tissue keeps making thick escape forks instead of freezing its topology.
      const edge = this.branchCount % 4;
      const position = 0.15 + (this.branchCount * 0.61803398875 % 1) * 0.7;
      const reach = Math.min(this.width, this.height) * (0.12 + 0.18 * (1 - Math.exp(-this.pressure / 12)));
      x = edge === 0 ? -reach : edge === 2 ? this.width + reach : this.width * position;
      y = edge === 1 ? -reach : edge === 3 ? this.height + reach : this.height * position;
    }
    let parent = -1, anchor = -1, nearest = Infinity;
    const p = this.particles;
    for (let index = 0; index < this.rootCount; index++) {
      const root = this.roots[index];
      if (!root.retained || root.merging || root.worm || root.depth !== this.growthFrontier || root.children >= 4 || root.count < 14 || (absorb && index === crowded)) continue;
      for (let joint = 8; joint < root.count - 4; joint += 8) {
        const id = root.ids[joint], distance = (p.x[id] - x) ** 2 + (p.y[id] - y) ** 2;
        if (distance < 3600 || distance >= nearest) continue;
        nearest = distance; parent = index; anchor = id;
      }
    }
    if (parent < 0) return;
    if (absorb) {
      const root = this.roots[crowded];
      root.retained = false;
      this.beginMerge(root, root.parentRoot);
    }
    const index = this.spawn(parent, anchor);
    if (index === undefined) return;
    const root = this.roots[index];
    root.targetX = x; root.targetY = y;
    root.angle = Math.atan2(y - p.y[anchor], x - p.x[anchor]);
    root.limit = Math.max(24, Math.ceil(Math.sqrt(nearest) / (SEGMENT * (1 + this.age * 0.012))) + 16);
  }

  private beginMerge(root: ReturnType<typeof makeRoot>, target: number) {
    const p = this.particles, parent = this.roots[target];
    root.merging = true; root.mergeTarget = target;
    root.mergeAge = this.age; root.mergedVolume = 0;
    root.mergeJoint = target === root.parentRoot && root.parentJoint >= 0 ? parent.ids.indexOf(root.parentJoint) : -1;
    if (root.mergeJoint < 0) {
      let nearest = Infinity;
      const source = root.ids[Math.floor(root.count / 2)];
      for (let joint = 0; joint < parent.count; joint++) {
        const id = parent.ids[joint], dx = p.x[id] - p.x[source], dy = p.y[id] - p.y[source];
        const distance = dx * dx + dy * dy;
        if (distance < nearest) { nearest = distance; root.mergeJoint = joint; }
      }
    }
    for (let joint = 0; joint < root.count; joint++) {
      const id = root.ids[joint];
      root.pathX[joint] = p.x[id]; root.pathY[joint] = p.y[id];
      if (joint > 0 || root.parentJoint < 0) {
        // A mature fork borrows its birth girth. Returning that girth as new tissue causes exponential feedback.
        const inherited = root.born >= this.consolidationAge && this.maturation !== "SPREADING" ? p.baseRadius[id] ** 2 : 0;
        root.mergedVolume += Math.max(0, p.radius[id] ** 2 - inherited) * Math.max(1, p.length[id]);
      }
    }
  }

  private merge(root: ReturnType<typeof makeRoot>) {
    const p = this.particles, parent = this.roots[root.mergeTarget];
    const time = Math.min(1, (this.age - root.mergeAge) / 1.8);
    const previous = Math.max(0, time - FIXED_STEP / 1.8);
    const ease = time * time * (3 - 2 * time);
    const flow = ease - previous * previous * (3 - 2 * previous);
    const anchor = root.ids[0];
    const offsetX = root.parentJoint >= 0 ? p.x[anchor] - root.pathX[0] : 0;
    const offsetY = root.parentJoint >= 0 ? p.y[anchor] - root.pathY[0] : 0;
    for (let joint = root.parentJoint >= 0 ? 1 : 0; joint < root.count; joint++) {
      const id = root.ids[joint];
      const destination = parent.ids[Math.min(parent.count - 1, root.mergeJoint + Math.floor(joint * 0.45))];
      p.x[id] = (root.pathX[joint] + offsetX) * (1 - ease) + p.x[destination] * ease;
      p.y[id] = (root.pathY[joint] + offsetY) * (1 - ease) + p.y[destination] * ease;
      p.previousX[id] = p.x[id]; p.previousY[id] = p.y[id];
    }
    const first = Math.max(0, root.mergeJoint - 18), last = Math.min(parent.count - 1, root.mergeJoint + 24);
    let weight = 0;
    for (let joint = first; joint <= last; joint++) weight += Math.max(1, p.length[parent.ids[joint]]) / (1 + Math.abs(joint - root.mergeJoint) * 0.12);
    for (let joint = first; joint <= last; joint++) {
      const id = parent.ids[joint];
      p.tissue[id] += root.mergedVolume * flow / Math.max(1, weight) / (1 + Math.abs(joint - root.mergeJoint) * 0.12);
    }
    this.absorbedVolume += root.mergedVolume * flow;
    if (time >= 1) {
      for (let joint = root.parentJoint >= 0 ? 1 : 0; joint < root.count; joint++) p.release(root.ids[joint]);
      if (this.maturation !== "SPREADING") this.culledRoots++;
      root.count = 0; root.merging = false;
      this.recycledBranches++;
    }
  }

  private grow() {
    const p = this.particles;
    const intensity = Math.min(1, this.age / (this.config.fullInfectionDelay / 1000));
    const speed = this.config.growthSpeed * (0.35 + intensity * 1.65);
    const spreading = this.maturation === "SPREADING";
    if (spreading) { this.updateFrontier(); this.recycle(); }
    else if (this.maturation === "CONSOLIDATING") this.consolidate();
    if (!spreading) this.renewForks();
    this.wrappedTips = 0;
    if (spreading && this.age >= this.nextSpawn) {
      if (this.rootCount < Math.min(6, this.config.maxRoots) || this.random() < Math.min(1, this.config.branchingProbability / 0.075)) this.spawn();
      this.nextSpawn = this.age + Math.max(0.18, 0.6 - intensity * 0.4);
    }
    if (this.age >= this.nextCrawl) {
      this.emit("crawl");
      this.nextCrawl = this.age + 0.5 + this.random();
    }
    const growingRoots = this.rootCount;
    for (let offset = 0; offset < growingRoots; offset++) {
      const index = (offset + this.tick) % growingRoots;
      const root = this.roots[index];
      if (root.count < 2) continue;
      const tip = root.ids[root.count - 1];
      if (root.merging) { this.merge(root); continue; }
      const targetDistance = Math.hypot(p.x[tip] - root.targetX, p.y[tip] - root.targetY);
      const edgeReached = (root.targetX < 16 && p.x[tip] < 32) || (root.targetX > this.width - 16 && p.x[tip] > this.width - 32)
        || (root.targetY < 16 && p.y[tip] < 32) || (root.targetY > this.height - 16 && p.y[tip] > this.height - 32);
      if (root.depth === 0 ? edgeReached : targetDistance < 28) root.targetReached = true;
      const anchor = root.ids[0];
      const reach = Math.hypot(root.targetX - p.x[anchor], root.targetY - p.y[anchor]);
      const pathBudget = Math.max(128, reach * 1.4 + 64 + root.width);
      const advancing = root.retained && !root.targetReached;
      const expanding = spreading || (advancing && root.totalLength < pathBudget);
      if (this.age >= root.nextTurn) {
        if (spreading && ((root.depth > 0 && this.random() < 0.3) || targetDistance < 50)) this.chooseTarget(root, index + 7);
        root.nextTurn = this.age + 1.5 + this.random() * 2;
      }
